function dashboard(){var clicks=D.publications.reduce(function(s,p){return s+Number(p.clicks||0)},0),active=D.monitors.filter(function(x){return x.status==='ACTIVE'}).length,ready=D.publications.filter(function(x){return x.status==='READY'||x.status==='SCHEDULED'}).length,usableGroups=D.groups.filter(function(g){return g.status==='ACTIVE'&&String(g.externalId||'').trim()}).length,validatedMarketplaces=(D.suite.marketplaces||[]).filter(function(x){return x.status==='ACTIVE'&&String(x.affiliateTag||'').trim()}).length,activeConnections=(D.suite.connections||[]).filter(function(x){return x.status==='ACTIVE'}).length+(D.suite.telegramConnections||[]).filter(function(x){return x.status==='ACTIVE'}).length,operationOn=active>0&&usableGroups>0&&validatedMarketplaces>0&&activeConnections>0;return '<section class="hero"><div><div class="eyebrow" style="color:#61e7ba">OPERAÇÃO INTELIGENTE</div><h2>Da oferta encontrada ao grupo certo, sem trabalho repetitivo.</h2><p>Monitore fontes, converta links, use IA para categorizar, organize filas e envie a imagem do produto junto com texto e link.</p><div class="actions"><button type=\"button\" id=\"create-promotion\" class=\"btn\" onclick=\"show(\'quick\')\">Criar promoção</button><button type="button" id="configure-monitor" class="btn secondary" onclick="show(\'monitoring\')">Configurar monitor</button></div></div><div class="pulsebox"><div class="pulse"><span>Motor de automação</span><i class="dot"></i></div><strong>'+(operationOn?'24/7 ativo':'Em configuração')+'</strong><small>'+active+' monitor(es) · '+usableGroups+' destino(s) utilizável(is) · '+ready+' item(ns) na fila</small></div></section><div class="metrics">'+metric('Ofertas capturadas',D.offers.length,'total no radar')+metric('Destinos utilizáveis',usableGroups,'ativos e com ID oficial')+metric('Envios na fila',ready,'prontos ou agendados')+metric('Cliques rastreados',clicks,'links publicados')+'</div>'+section('Quatro modos de operação','Escolha entre controle total e automação completa.')+'<div class="grid modes">'+mode('MODO 01','Monitoramento inteligente','Captura, valida, converte e distribui ofertas automaticamente.','monitoring')+mode('MODO 02','Clone fiel','Preserva texto e imagem; substitui somente links e cupons.','clone')+mode('MODO 03','Sob demanda','Cole um link e prepare a oferta em poucos segundos.','quick')+mode('MODO 04','Filas programadas','Horários, intervalos e recorrências por nicho.','queues')+'</div><div class="grid two">'+recent()+'<div>'+section('Atividade recente','O que o sistema executou.')+'<div class="card"><ul class="activity">'+(D.activity.length?D.activity.slice(0,7).map(function(a){return '<li><i class="a-dot"></i><div><b>'+esc(a.title)+'</b><div class="muted">'+esc(a.details)+'</div></div><time>'+new Date(a.createdAt).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})+'</time></li>'}).join(''):'<li><i class="a-dot"></i><div><b>Sistema pronto</b><div class="muted">Configure as integrações para iniciar.</div></div></li>')+'</ul></div></div></div>'}
function metric(a,b,c){return '<div class="metric"><label>'+a+'</label><b>'+b+'</b><small>'+c+'</small></div>'}function modeReady(target){var groups=D.groups.some(function(g){return g.status==='ACTIVE'&&String(g.externalId||'').trim()}),stores=(D.suite.marketplaces||[]).some(function(x){return x.status==='ACTIVE'&&String(x.affiliateTag||'').trim()}),delivery=(D.suite.connections||[]).some(function(x){return x.status==='ACTIVE'})||(D.suite.telegramConnections||[]).some(function(x){return x.status==='ACTIVE'}),monitors=D.monitors.some(function(x){return x.status==='ACTIVE'}),queues=D.queues.some(function(x){return x.status==='ACTIVE'});if(target==='quick')return stores;if(target==='queues')return queues&&groups;if(target==='monitoring'||target==='clone')return monitors&&stores&&groups&&delivery;return false}function mode(code,title,text,target){var ready=modeReady(target);return '<div class="card mode"><div class="code">'+code+'</div><h3>'+title+'</h3><p>'+text+'</p><div class="state"><b class="'+(ready?'':'muted')+'">'+(ready?'Configurado':'Configuração necessária')+'</b><button class="btn secondary" onclick="show(\''+target+'\')">Abrir</button></div></div>'}function recent(){return '<div>'+section('Ofertas recentes','Prioridade maior primeiro.','Ver todas','show(\'offers\')')+'<div class="list">'+(D.offers.length?D.offers.slice(0,4).map(offerRow).join(''):empty('Nenhuma oferta cadastrada'))+'</div></div>'}
function monitoring(){return section('Fontes e regras de monitoramento','Cadastre fontes autorizadas. A captura automática só fica ativa quando o conector da origem estiver validado.','+ Nova fonte','openMonitor()')+'<div class=\"card\"><div class=\"steps\">'+['Recebe do conector','Detecta produto','Valida oferta','Converte link','Direciona ao grupo'].map(function(x,i){return '<div class=\"step\"><i>0'+(i+1)+'</i><b>'+x+'</b></div>'}).join('')+'</div><div class=\"callout\" style=\"margin-top:15px\">Cadastrar uma fonte não autoriza leitura automática do WhatsApp, de redes sociais ou de marketplaces. É necessário um conector oficial e credenciais válidas.</div></div>'+section('Fontes cadastradas','Mantenha a origem pausada até validar o conector.')+'<div class=\"list\">'+(D.monitors.length?D.monitors.map(function(m){var c=cat(m.categoryId);return '<div class=\"row\"><div class=\"intlogo\">CN</div><div class=\"grow\"><b>'+esc(m.name)+'</b><div class=\"muted\">'+esc(m.sourceType)+' · '+(c?esc(c.name):'Todas as categorias')+' · '+m.capturedCount+' capturas reais</div></div><span class=\"pill '+(m.status==='ACTIVE'?'live':'warn')+'\">'+LABEL[m.status]+'</span>'+(m.status==='ACTIVE'?'<button class=\"btn secondary\" onclick=\"status(\'monitor\',\''+m.id+'\',\'PAUSED\')\">Pausar</button>':'<button class=\"btn secondary\" disabled title=\"Exige conector oficial\">Conector necessário</button>')+'</div>'}).join(''):empty('Nenhuma fonte cadastrada'))+'</div>'}
function cloneView(){return section('Modo clone','Preserva conteúdo e troca somente links rastreáveis.')+'<div class="grid two"><div class="card"><h3>Fluxo protegido</h3><div class="steps">'+['Captura','Identifica links','Converte','Mantém mídia','Enfileira'].map(function(x,i){return '<div class="step"><i>0'+(i+1)+'</i><b>'+x+'</b></div>'}).join('')+'</div><div class="callout" style="margin-top:15px">Mensagens com vários produtos ficam para revisão. O sistema não altera preço, cupom ou frete sem confirmação da fonte.</div></div><div class="card"><h3>Regras do clone</h3><p class="muted">✓ Preservar formatação e imagem<br>✓ Substituir links reconhecidos<br>✓ Gerar link de cupom quando disponível<br>✓ Bloquear duplicações<br>✓ Enviar à categoria compatível</p><button class="btn" onclick="openMonitor()">Adicionar origem</button></div></div>'}
function quick(){return section('Criação rápida','Converta um link configurado ou cadastre uma oferta completa.','+ Cadastrar oferta','openOffer()')+'<div class="grid two"><div class="card"><h3>Conversor oficial</h3><p class="muted">Reconhece as lojas cadastradas. A conversão só é liberada quando o método oficial daquela conta está validado.</p><div class="field"><label>Link do produto</label><input class="input" id="convertUrl" type="url" placeholder="https://..."></div><div class="field" style="margin-top:10px"><label>Identificação do grupo</label><input class="input" id="convertGroup" value="geral"></div><button class="btn" style="margin-top:12px" onclick="convertLink()">Converter link</button><div id="convertResult" class="callout" style="display:none;margin-top:12px"></div></div><div class="card"><div class="steps">'+['Cole o link','Confira o produto','IA cria o texto','Escolha os grupos','Envie ou agende'].map(function(x,i){return '<div class="step"><i>0'+(i+1)+'</i><b>'+x+'</b></div>'}).join('')+'</div></div></div>'+recent()}
function queues(){return section('Filas e agendamentos','Defina janelas e intervalos das publicações. Recorrências abaixo são planejamento até o executor próprio ser habilitado.','+ Nova fila','openQueue()')+'<div class="grid two"><div><div class="list">'+(D.queues.length?D.queues.map(function(q){var c=cat(q.categoryId);return '<div class="row"><div class="intlogo">FQ</div><div class="grow"><b>'+esc(q.name)+'</b><div class="muted">'+(c?esc(c.name):'Geral')+' · '+q.startTime+'–'+q.endTime+' · intervalo '+q.intervalMinutes+' min</div></div><span class="pill live">'+LABEL[q.status]+'</span></div>'}).join(''):empty('Nenhuma fila criada'))+'</div></div><div><div class="sectionhead" style="margin-top:0"><div><h2>Recorrências planejadas</h2><p>Registro de planejamento; envio recorrente automático ainda não habilitado.</p></div><button class=\"btn secondary\" onclick=\"openSchedule()\">+ Registrar</button></div><div class="list">'+(D.schedules.length?D.schedules.map(function(s){return '<div class="row"><div class="grow"><b>'+esc(s.name)+'</b><div class="muted">'+s.recurrence+' às '+s.sendTime+'</div></div><span class="pill live">'+LABEL[s.status]+'</span></div>'}).join(''):empty('Nenhuma recorrência'))+'</div></div></div>'+section('Publicações','Imagem, texto e link seguem no mesmo envio.')+'<div class="list">'+(D.publications.length?D.publications.map(publicationRow).join(''):empty('Fila vazia'))+'</div>'}
function publicationRow(p){var o=off(p.offerId),g=grp(p.groupId);return '<div class="row">'+(o?thumb(o):'')+'<div class="grow"><b>'+esc(o?o.title:'Oferta removida')+'</b><div class="muted">'+esc(g?g.name:'Grupo removido')+' · '+esc(g?.platform||'WHATSAPP')+' · '+(LABEL[p.status]||p.status)+' · '+p.mode+' · '+p.clicks+' cliques</div></div><div class="actions"><button class="btn" '+(p.status==='PUBLISHED'?'disabled':'')+' onclick="share(\''+p.id+'\')">Compartilhar</button><button class="btn danger" onclick="removeItem(\'publication\',\''+p.id+'\')">Excluir</button></div></div>'}
function offers(){return section('Central de ofertas','Produtos encontrados, aprovados e publicados.','+ Nova oferta','openOffer()')+'<div class="list">'+(D.offers.length?D.offers.map(offerRow).join(''):empty('Nenhuma oferta'))+'</div>'+section('Modelos de mensagens','Formatos prontos inspirados nos exemplos enviados. Preços, descontos e cupons só aparecem quando informados.')+'<div class="grid three">'+messageExample('🤯 Impactante','🤯 *OLHA ESSE PREÇO!*\n🔥 Achadinho com preço especial\n\n💗 Kit 3 Escovas de Cabelo\n🏷️ *10% OFF*\nDe: ~R$ 29,99~\n*POR: R$ 26,99* ✅\n\n🔗 *COMPRE AQUI* 👇')+messageExample('🚨 Oferta completa','🚨 *CHEGOU PROMOÇÃO!*\n🛍️ Oferta encontrada para você\n\n💗 Cadeira para Auto\n🏷️ *46% OFF*\nDe: ~R$ 999,90~\n*POR: R$ 539,12* ✅\n\n🔗 *COMPRE AQUI* 👇')+messageExample('🌍 Produtos importados','🌍 *ACHADINHO IMPORTADO!*\n📦 Produto importado em oferta\n\n💗 Produto selecionado\nDe: ~R$ 89,90~\n*POR: R$ 59,90* ✅\n\n🔗 *COMPRE AQUI* 👇')+'</div>'}
function messageExample(title,text){return '<div class="card"><h3>'+title+'</h3><div class="callout" style="white-space:pre-wrap">'+esc(text)+'</div></div>'}
function groups(){return section('Grupos e canais por categoria','Somente destinos ativos e com ID oficial entram nas filas.','+ Novo destino','openGroup()')+'<div class=\"tablewrap\"><table class=\"table\"><thead><tr><th>Grupo/canal</th><th>Plataforma</th><th>Categoria</th><th>Membros</th><th>Status</th><th>Ação</th></tr></thead><tbody>'+D.groups.map(function(g){var c=cat(g.categoryId),lot=Math.round(Number(g.members||0)*100/Number(g.capacity||1024)),hasId=Boolean(String(g.externalId||'').trim());return '<tr><td><b>'+esc(g.name)+'</b><div class=\"bar\"><i style=\"width:'+Math.min(100,lot)+'%\"></i></div><small class=\"muted\">'+esc(g.externalId||'ID de destino pendente')+'</small></td><td><span class=\"pill '+(g.platform==='TELEGRAM'?'live':'')+'\">'+esc(g.platform||'WHATSAPP')+'</span></td><td>'+(c?c.icon+' '+esc(c.name):'Geral')+'</td><td>'+g.members+' / '+g.capacity+'</td><td><span class=\"pill '+(g.status==='ACTIVE'&&hasId?'live':'warn')+'\">'+(hasId?LABEL[g.status]:'Configuração pendente')+'</span></td><td><div class=\"actions\"><button class=\"btn secondary\" onclick=\"openGroup(\''+g.id+'\')\">Configurar</button>'+(hasId?'<button class=\"btn secondary\" onclick=\"status(\'group\',\''+g.id+'\',\''+(g.status==='ACTIVE'?'PAUSED':'ACTIVE')+'\')\">'+(g.status==='ACTIVE'?'Pausar':'Ativar')+'</button>':'')+(g.platform==='TELEGRAM'&&hasId?'<button class=\"btn dark\" onclick=\"testTelegram(\''+g.id+'\')\">Testar</button>':'')+'</div></td></tr>'}).join('')+'</tbody></table></div>'}
function leads(){var unique=D.leadStats.reduce(function(s,x){return s+Number(x.unique_leads||0)},0),joined=D.leadStats.reduce(function(s,x){return s+Number(x.joined||0)},0),left=D.leadStats.reduce(function(s,x){return s+Number(x.left||0)},0),members=D.groups.reduce(function(s,g){return s+Number(g.members||0)},0);return section('Gestão de leads','Retenção, lotação e desempenho real por grupo.')+'<div class="leadhero">'+metric('Leads ativos',members,'membros informados')+metric('Leads únicos 30d',unique,'sem duplicidade')+metric('Entradas 30d',joined,'novos participantes')+metric('Saídas 30d',left,'acompanhar retenção')+'</div>'+section('Raio-X dos grupos','Capacidade e movimentação.')+'<div class="grid three">'+D.groups.map(function(g){var fill=Math.round(Number(g.members||0)*100/Number(g.capacity||1024));return '<div class="card leadmetric"><span class="muted">'+esc(g.name)+'</span><b>'+fill+'%</b><div class="bar"><i style="width:'+Math.min(100,fill)+'%"></i></div><div class="muted">'+g.members+' membros · '+Math.max(0,g.capacity-g.members)+' vagas</div>'+(fill>=90?'<div class="callout" style="margin-top:10px">Grupo próximo da lotação.</div>':'')+'</div>'}).join('')+'</div>'}
function reportTable(items,label){return '<div class="tablewrap"><table class="table"><thead><tr><th>'+label+'</th><th>Links</th><th>Cliques</th><th>Vendas</th><th>Conversão</th><th>Comissão</th></tr></thead><tbody>'+(items.length?items.map(function(x){var clicks=Number(x.clicks||0),sales=Number(x.sales||0);return '<tr><td><b>'+esc(x.name||x.title||'—')+'</b></td><td>'+Number(x.shared||0)+'</td><td>'+clicks+'</td><td>'+sales+'</td><td>'+(clicks?(sales*100/clicks).toFixed(1):'0,0')+'%</td><td>'+brl(x.commission||0)+'</td></tr>'}).join(''):'<tr><td colspan="6">Sem dados no período.</td></tr>')+'</tbody></table></div>'}
function reports(){var r=D.reportsData||{},s=r.summary||{},max=Math.max(1,...(r.daily||[]).map(function(x){return Number(x.clicks||0)}));return '<div class="sectionhead"><div><h2>Relatórios</h2><p>Resultados reais por período, categoria, grupo, canal e marketplace.</p></div><div class="toolbar"><select class="input" onchange="changeReportDays(this.value)"><option value="7" '+(reportDays===7?'selected':'')+'>7 dias</option><option value="30" '+(reportDays===30?'selected':'')+'>30 dias</option><option value="90" '+(reportDays===90?'selected':'')+'>90 dias</option><option value="365" '+(reportDays===365?'selected':'')+'>12 meses</option></select><button class="btn" onclick="openSale()">+ Registrar venda</button></div></div><div class="metrics">'+metric('Links compartilhados',s.shared||0,'publicações concluídas')+metric('Cliques',s.clicks||0,'eventos rastreados')+metric('Vendas',s.sales||0,'pedidos não cancelados')+metric('Comissões',brl(s.commission||0),'valor importado')+'</div><div class="metrics">'+metric('Receita gerada',brl(s.revenue||0),'valor dos pedidos')+metric('Conversão',(s.conversionRate||0)+'%','vendas por clique')+metric('Ticket médio',brl(s.averageTicket||0),'por venda')+metric('Comissão média',brl(s.averageCommission||0),'por venda')+'</div><div class="callout">Vendas e comissões são importadas dos relatórios oficiais ou registradas manualmente. O sistema não estima valores.</div>'+section('Evolução diária','Cliques registrados nos últimos '+reportDays+' dias.')+'<div class="card" style="display:flex;align-items:flex-end;gap:4px;height:180px;overflow:auto">'+(r.daily||[]).map(function(x){var h=Math.max(4,Math.round(Number(x.clicks||0)*120/max));return '<div title="'+esc(x.day)+' · '+x.clicks+' cliques" style="min-width:18px;flex:1;text-align:center"><div style="height:'+h+'px;background:var(--orange);border-radius:5px 5px 0 0"></div><small class="muted">'+String(x.day).slice(8,10)+'</small></div>'}).join('')+'</div>'+section('Por canal de envio','Compare WhatsApp e Telegram.')+reportTable(r.byChannel||[],'Canal')+section('Por marketplace','Amazon, Shopee e Mercado Livre.')+reportTable(r.byPlatform||[],'Marketplace')+section('Por categoria','Descubra os nichos com mais retorno.')+reportTable(r.byCategory||[],'Categoria')+section('Por grupo','Compare cliques, vendas e comissão.')+reportTable(r.byGroup||[],'Grupo')+section('Melhores ofertas','Ranking por comissão e cliques.')+reportTable(r.topOffers||[],'Oferta')+section('Saúde dos envios','Situação das publicações no período.')+'<div class="grid three">'+(r.delivery||[]).map(function(x){return '<div class="card"><span class="pill">'+esc(x.status)+'</span><b style="font-size:28px;display:block;margin-top:9px">'+x.total+'</b></div>'}).join('')+'</div>'}
function integrations(){return section('Integrações','Conecte cada serviço para ativar a automação completa.')+'<div class="grid two"><div class="card">'+integration('ML','Mercado Livre','Produtos e OAuth preparados; teste real depende da credencial.','Preparado')+integration('SH','Shopee Afiliados','Conversão depende do acesso oficial da sua conta.','Configurar')+integration('AMZ','Amazon Associados','Tags e SubIDs por grupo.','Configurar')+integration('MKP','Shein, AliExpress, Magalu, Casas Bahia, Hotmart e outras','Catálogo e regras por conta adicionados; conectores oficiais ficam bloqueados até validação.','Preparado')+integration('WA','WhatsApp','Envio com imagem via ponte segura com n8n.','Configurar')+integration('TG','Telegram','Bot oficial envia imagem, texto, botão e link.','Disponível')+integration('META','Facebook e Instagram','Publicação oficial aguarda autorização OAuth da conta profissional.','Conectar')+integration('MAIL','Gmail e Outlook','Entrega transacional já funciona; remetente próprio exige domínio ou OAuth.','Disponível')+integration('GEM','Google Gemini','Textos, anúncios, cupons, legendas, carrosséis e roteiros testados.','Testado')+integration('GPT','OpenAI e Claude','Conectores prontos; cada provedor exige sua própria chave.','Credencial')+integration('IMG','IA de imagem','Provedor principal + Runway + cartão promocional automático em caso de limite.','Disponível')+integration('VID','IA de vídeo','Fila real de renderização Runway, consulta de estado e armazenamento protegido.','Disponível')+'</div><div class="card"><h3>Teste interno do fluxo</h3><p class="muted">Valida produto, preço, imagem e link; classifica a categoria, escolhe grupos e monta a mensagem sem envio externo.</p><button class="btn dark" onclick="runSimulation()">Executar teste seguro</button><div id="simulationResult" class="callout" style="margin-top:12px;display:none"></div><h3 style="margin-top:22px">Estados reais</h3><p class="muted">Testado: executado com sucesso nest