function prepare(id){selected=off(id);if(!selected||!selected.imageUrl)return toast('A oferta precisa de uma imagem.');var groups=D.groups.filter(function(g){return g.status==='ACTIVE'&&String(g.externalId||'').trim()&&(g.categoryId===selected.categoryId||!g.categoryId)});if(!groups.length)groups=D.groups.filter(function(g){return g.status==='ACTIVE'&&String(g.externalId||'').trim()});if(!groups.length)return toast('Configure um grupo ou canal com ID oficial antes de preparar o envio.');openModal('Preparar envio','Imagem, mensagem e link seguirão juntos.',select('Grupo','groupId',groups.map(function(g){return '<option value="'+g.id+'">'+esc(g.name)+'</option>'}).join(''))+select('Modo','mode','<option value="ON_DEMAND">Sob demanda</option><option value="SMART">Inteligente</option><option value="CLONE">Clone</option>')+select('Prioridade','priority','<option value="NORMAL">Normal</option><option value="FLASH">Fura-fila</option>')+select('Marcar todos','mentionAll','<option value="false">Não</option><option value="true">Solicitar ao conector</option>')+field('Agendar para','scheduledAt','datetime-local')+'<div class="field"><label>Mensagem</label><textarea class="input" name="message" rows="8">'+esc(selected.message)+'</textarea></div>',async function(e){e.preventDefault();try{await call('POST',Object.assign({entity:'publication',offerId:selected.id},Object.fromEntries(new FormData(e.target))));closeModal();show('queues');toast('Publicação adicionada à fila')}catch(err){toast(err.message)}})}
async function status(entity,id,value){try{await call('PUT',{entity:entity,id:id,status:value});toast('Status atualizado')}catch(e){toast(e.message)}}async function removeItem(entity,id){if(!confirm('Deseja realmente excluir?'))return;try{await call('DELETE',null,'?entity='+encodeURIComponent(entity)+'&id='+encodeURIComponent(id));toast('Item excluído')}catch(e){toast(e.message)}}
async function share(id){var p=D.publications.find(function(x){return x.id===id}),o=off(p.offerId),g=grp(p.groupId);if(!o||!o.imageUrl)return toast('Imagem não encontrada.');var text=(p.message||o.message)+'\n\nDestino: '+(g?g.name:'Grupo');try{var r=await fetch(o.imageUrl),blob=await r.blob(),file=new File([blob],'oferta.'+(blob.type.split('/')[1]||'jpg'),{type:blob.type});if(navigator.canShare&&navigator.canShare({files:[file]})){await navigator.share({title:o.title,text:text,files:[file]});await status('publication',id,'PUBLISHED')}else{await navigator.clipboard.writeText(text);window.open(o.affiliateUrl,'_blank','noopener');toast('Texto copiado. Anexe a imagem ao WhatsApp.')}}catch(e){if(e.name!=='AbortError')toast('Não foi possível compartilhar.')}}
nav();load();
